import { describe, it, expect, beforeEach } from '@jest/globals';
import request from 'supertest';
import { resetRateLimiterState } from '../../src/middleware/rateLimiter';

describe('Debug JWT Registration', () => {
  let app: any;

  beforeEach(async () => {
    // Reset rate limiter state to avoid test interference
    resetRateLimiterState();
    
    // Import the actual app
    const appModule = await import('../../src/index');
    app = appModule.app;
    
    // Give the app a moment to initialize
    await new Promise((resolve) => setTimeout(resolve, 100));
  });

  it('should register a user for JWT tests', async () => {
    const uniqueEmail = `jwt-test-${Date.now()}@example.com`;
    const testUser = {
      email: uniqueEmail,
      password: 'SecureTestPassword123!',
      name: 'Test User',
    };

    console.log('Attempting to register:', testUser);

    const registerResponse = await request(app)
      .post('/api/auth/register')
      .send(testUser);

    console.log('Registration response status:', registerResponse.status);
    console.log('Registration response body:', JSON.stringify(registerResponse.body, null, 2));

    expect(registerResponse.status).toBe(201);
    expect(registerResponse.body.user).toBeDefined();
    expect(registerResponse.body.accessToken || registerResponse.body.token).toBeDefined();
  });
});